def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    # Extract opponent sequence
    opp = [h[1] for h in history]
    own = [h[0] for h in history]
    last_opp = opp[-1]
    last_own = own[-1]

    # --- Phase 1: opening probes (first 4 rounds) ---
    if n < 4:
        # Cooperate first, then small probe pattern to test responsiveness.
        # After 10 externally supplied CC rounds in probes, this often won't trigger,
        # but early match opening should be cooperative-friendly.
        return 'C'

    # --- Helper computations (n >= 4) ---
    # Consecutive defections at end of opponent history
    consec_opp_d = 0
    for a in reversed(opp):
        if a == 'D':
            consec_opp_d += 1
        else:
            break
    # Consecutive cooperation at end
    consec_opp_c = 0
    for a in reversed(opp):
        if a == 'C':
            consec_opp_c += 1
        else:
            break

    opp_d_total = 0
    for a in opp:
        if a == 'D':
            opp_d_total += 1
    own_d_total = 0
    for a in own:
        if a == 'D':
            own_d_total += 1
    opp_rate = opp_d_total / float(n)
    remaining = 100 - n

    # --- Strong sustained defector detection ---
    # If opponent has been defecting heavily, punish hard (avoid being a sucker).
    if opp_rate >= 0.7 and n >= 8:
        # Mostly defect, but rare probe to catch conditional cooperators.
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # --- Endgame: defect late to secure terminal payoff ---
    if remaining <= 2:
        return 'D'

    # --- Sustained defection handling (recent streak) ---
    if consec_opp_d >= 3:
        # Punish sustained defection.
        if consec_opp_d >= 5:
            return 'D'
        # For moderate streaks, defect but occasionally forgive to test.
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # --- Immediate retaliation for a fresh defection ---
    if last_opp == 'D':
        if consec_opp_d == 1:
            # Single defection: retaliate unless we ourselves defected last
            # (which suggests the opponent may be mirroring us).
            if last_own == 'D':
                # Opponent may be TFT-like; return to cooperation to restore CC.
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            return 'D'
        # consec_opp_d == 2
        if last_own == 'D':
            # We're in a DD exchange; try to restore cooperation sometimes.
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    # --- Opponent just cooperated ---
    # If we defected last round and opponent still cooperated, reward them
    # with cooperation (forgiving/generous response).
    if last_own == 'D':
        # But watch out: if opponent has high defection rate, they may be
        # baiting us with a C then defecting. Still, defecting on a C loses 3-5.
        if opp_rate > 0.5:
            # Moderate defection history: cooperate to test, mostly.
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        return 'C'

    # --- Both cooperated recently: maintain CC ---
    # Adaptive exploitation only when opponent is extremely cooperative
    # and we have a big score lead opportunity near mid/late game.
    if n >= 20 and opp_rate < 0.08:
        # Very cooperative opponent. Exploit sparingly in mid game.
        if n > 90:
            # Near endgame, defect aggressively (already covered by remaining<=2,
            # but extend a bit).
            return 'D'
        if n > 50:
            # Mid-late: occasional defection to grab 5.
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        # Early-mid: mostly cooperate to build trust, occasional probe.
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # --- Moderate opponent: reciprocate with generous tit-for-tat ---
    if n >= 10:
        # Count opponent defections in last 10 rounds
        recent = opp[-10:]
        recent_d = 0
        for a in recent:
            if a == 'D':
                recent_d += 1
        if recent_d >= 4:
            # Recent hostility: defect more.
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        if recent_d == 3:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        if recent_d == 2:
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        if recent_d == 1:
            # Mostly cooperate; slight inclination to test.
            if rng.random() < 0.9:
                return 'C'
            return 'D'
        # recent_d == 0
        if n >= 30 and opp_rate < 0.2:
            if rng.random() < 0.15:
                return 'D'
            return 'C'
        return 'C'

    # Default: cooperate.
    return 'C'
